/*
 * Copy-first port of node_modules/@salesforce/retail-react-app/app/components/product-item/index.jsx
 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
 * plan step 2.1). Zero functional diff at that step — TypeScript annotations, the import path
 * rewrites documented below, and a temporary `[overrides]` console.log marker (verified live
 * against three real surfaces per the plan's copy-first stop, then removed) were the only
 * changes; styling/behaviour changes are this commit (plan step 2.2, see below), not that one.
 *
 * Import path rewrites, per .claude/rules/overrideStyling.md's "Importing an already-overridden
 * component from a new component":
 * - `item-variant` / `item-variant/item-image` / `item-variant/item-name` /
 *   `item-variant/item-attributes` / `item-variant/item-price`: this repo overrides all five
 *   (SFCC-270, this same commit), so these are relative imports rather than the base
 *   `@salesforce/retail-react-app/...` path — a base-path import here would silently exercise the
 *   unstyled base components in Storybook/Vitest instead of these overrides.
 * - `./bonus-product-quantity` / `./product-quantity-picker`: same reasoning, both overridden in
 *   this same commit, in this same folder.
 * - `responsive` (`HideOnDesktop`/`HideOnMobile`): also already overridden in this repo
 *   (overrides/app/components/responsive/index.tsx) — and not just a styling port, a genuine
 *   behavioural difference (it moves the mobile/desktop split to Chakra's `md` breakpoint instead
 *   of the base's `lg`) — so this is rewritten to a relative import too, for the same reason.
 * - `shared/ui`, `loading-spinner`, `utils/utils`, and the `app/hooks` barrel (`useCurrency`/
 *   `useDerivedProduct`) are NOT overridden anywhere in this repo (verified by directory listing
 *   at time of writing) — these stay on the base `@salesforce/retail-react-app/...` path, since
 *   there is no local override to redirect to.
 *
 * `SfccProduct` is kept as `any` with a named alias rather than a structural type invented from
 * usage — this package ships no TypeScript types for this shape, matching the same documented gap
 * at overrides/app/components/product-view/index.tsx:136-151.
 *
 * SFCC-270 (plan step 2.2): restyled to the Figma cart-item spec via product-item.css.ts's
 * `ZimmCartItem` recipe (`row`/`details`/`info` parts, applied through `sx` — see that recipe's
 * own docblock for why `sx`, not `__css`, is required on a plain Flex/Stack here). The image's
 * own default width moved out of this file entirely — item-image.tsx now supplies its own
 * responsive default via item-variant.css.ts's `image` part, so the `mr`-based gap this file
 * used to add is replaced by the `row` part's own Figma-specified `gap`.
 * `CartItemVariantAttributes` now also renders with `combineAttributeValues`, per the Figma
 * spec's single "colour, size" string (see that component's own file). The two `display={[...]}`
 * responsive-array primaryAction visibility toggles are replaced with this file's own already-
 * imported `HideOnMobile`/`HideOnDesktop` (both already used here for `deliveryActions`) — the
 * original arrays split at Chakra's default `sm` (480px), one breakpoint earlier than this
 * file's own `md` (768px) split everywhere else; no Figma value distinguishes this, so it is
 * unified to the same `md` split as the rest of this file rather than preserved as a second,
 * unexplained breakpoint — flagged in this build's report as a disclosed interpretation, not a
 * tested requirement.
 *
 * Gift-card conditional stepper/actions suppression is NOT implemented at this step — see this
 * build's report for why (no real signal for a digital gift card line item was found anywhere in
 * this codebase or the commerce SDK types at time of writing; `GiftCertificateItem` exists in
 * the SDK but is a structurally different, wholly separate basket line-item shape that this
 * component's own render tree — `useDerivedProduct`, `ItemVariantProvider`'s `SfccProduct` shape
 * — is not built to receive at all).
 */
import React from 'react';

// Chakra Components
import { Box, Fade, Flex, Stack, Text, useMultiStyleConfig } from '@salesforce/retail-react-app/app/components/shared/ui';

// Project Components
import { HideOnDesktop, HideOnMobile } from '../responsive';
import ItemVariantProvider from '../item-variant';
import CartItemVariantImage from '../item-variant/item-image';
import CartItemVariantName from '../item-variant/item-name';
import CartItemVariantAttributes from '../item-variant/item-attributes';
import CartItemVariantPrice from '../item-variant/item-price';
import LoadingSpinner from '@salesforce/retail-react-app/app/components/loading-spinner';
import BonusProductQuantity from './bonus-product-quantity';
import ProductQuantityPicker from './product-quantity-picker';
import { ZimmCartItem } from './product-item.css';

// Utilities
import { noop } from '@salesforce/retail-react-app/app/utils/utils';

// Hooks
import { useCurrency, useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';

const ZIMM_CART_ITEM_RECIPE = 'ZimmCartItem';

type SfccProduct = any;

type ProductItemProps = {
  product: SfccProduct;
  primaryAction?: React.ReactNode;
  secondaryActions?: React.ReactNode;
  deliveryActions?: React.ReactNode;
  onItemQuantityChange?: (quantity: number) => any;
  /**
   * Declared on the base file's propTypes but never read inside this component's own render
   * body — kept here only to mirror that declared surface one-for-one (zero functional diff,
   * SFCC-270). No return-type guarantee to derive from PropTypes.func, so typed loosely.
   */
  onAddItemToCart?: (...args: any[]) => any;
  showLoading?: boolean;
  /** Declared on the base file's propTypes but never read inside this component's own render body — see onAddItemToCart above. */
  isWishlistItem?: boolean;
  containerStyles?: Record<string, any>;
  isRemoving?: boolean;
  pickupInStore?: boolean;
};

/**
 * Component representing a product item usually in a list with details about the product - name, variant, pricing, etc.
 * @param {Object} product Product to be represented in the list item.
 * @param {node} primaryAction Child component representing the most prominent action to be performed by the user.
 * @param {node} secondaryActions Child component representing the other actions relevant to the product to be performed by the user.
 * @param {node} deliveryActions Child component representing the delivery actions relevant to the product to be performed by the user.
 * @param {func} onItemQuantityChange callback function to be invoked whenever item quantity changes.
 * @param {boolean} showLoading Renders a loading spinner with overlay if set to true.
 * @returns A JSX element representing product item in a list (eg: wishlist, cart, etc).
 */
const ProductItem = ({
  product,
  primaryAction,
  secondaryActions,
  deliveryActions,
  onItemQuantityChange = noop,
  showLoading = false,
  containerStyles = {},
  isRemoving = false,
  pickupInStore = false,
}: ProductItemProps) => {
  const { stepQuantity, showInventoryMessage, inventoryMessage, quantity, setQuantity } = useDerivedProduct(
    product,
    false,
    false,
    pickupInStore,
  );
  const { currency: activeCurrency } = useCurrency();
  const styles = useMultiStyleConfig(ZIMM_CART_ITEM_RECIPE, {});
  return (
    <Box position="relative" data-testid={`sf-cart-item-${product.productId ? product.productId : product.id}`}>
      <ItemVariantProvider variant={product}>
        {showLoading && <LoadingSpinner />}
        <Stack layerStyle="cardBordered" align="flex-start" {...containerStyles}>
          <Flex sx={styles.row} width="full" backgroundColor="white">
            <CartItemVariantImage />
            <Stack sx={styles.details} flex={1}>
              <Flex sx={styles.info}>
                <Stack spacing={1}>
                  <CartItemVariantName />
                  <CartItemVariantAttributes excludeBonusLabel combineAttributeValues />
                  <HideOnDesktop>
                    <Box marginTop={2}>
                      <CartItemVariantPrice align="left" currency={activeCurrency} />
                    </Box>
                  </HideOnDesktop>
                </Stack>
                {deliveryActions && !product.bonusProductLineItem && <HideOnMobile>{deliveryActions}</HideOnMobile>}
              </Flex>

              {deliveryActions && !product.bonusProductLineItem && <HideOnDesktop>{deliveryActions}</HideOnDesktop>}

              <Flex align="flex-end" justify="space-between">
                <Stack spacing={1}>
                  {!(isRemoving && product.bonusProductLineItem) &&
                    (product.bonusProductLineItem ? (
                      <BonusProductQuantity product={product} />
                    ) : (
                      <ProductQuantityPicker
                        product={product}
                        onItemQuantityChange={onItemQuantityChange}
                        stepQuantity={stepQuantity}
                        quantity={quantity}
                        setQuantity={setQuantity}
                      />
                    ))}
                </Stack>
                <Stack>
                  <HideOnMobile>
                    <CartItemVariantPrice currency={activeCurrency} />
                  </HideOnMobile>
                  <HideOnMobile>{primaryAction}</HideOnMobile>
                </Stack>
              </Flex>

              <Box>
                {product && showInventoryMessage && (
                  <Fade in={true}>
                    <Text color="orange.600" fontWeight={600}>
                      {inventoryMessage}
                    </Text>
                  </Fade>
                )}
              </Box>

              {secondaryActions}
            </Stack>
          </Flex>

          <HideOnDesktop>
            <Box w={'full'}>{primaryAction}</Box>
          </HideOnDesktop>
        </Stack>
      </ItemVariantProvider>
    </Box>
  );
};

export default ProductItem;

import { breakpoints } from 'app/theme/foundation';

/**
 * Co-located recipe for the cart line-item shell (overrides/app/components/product-item).
 * SFCC-270 (plan step 2.2) — restyles the copy-first port to the Figma-sourced cart-item spec.
 *
 * Parts:
 *   - `row` — the image + item-details row. Figma: gap 28px desktop / 24px mobile, align
 *     centre desktop / start mobile.
 *   - `details` — the column beside the image (name/attrs/price/stepper/actions). Figma:
 *     gap 12px desktop / 24px mobile.
 *   - `info` — the name + colour/size (+ mobile price) block, paired with the desktop-only
 *     delivery-actions slot. Figma: column layout desktop / row + justify-space-between
 *     mobile. The mobile values match this block's pre-existing unconditional layout exactly
 *     (row, space-between, align flex-end) so nothing changes below `md` — only the desktop
 *     column switch is new.
 *
 * Applied via `sx`, not `__css`: `Flex`/`Stack` (`@chakra-ui/layout`'s `chunk-MPFPK3CX.mjs` /
 * `chunk-WKZT7ZXJ.mjs`) each pass their own computed `alignItems`/`justifyContent`/
 * `flexDirection`/`gap` as literal props ahead of `{...rest}` in their own render, and
 * `@chakra-ui/system`'s `toCSSObject` (`chunk-E32MZNBA.mjs`) merges
 * `assignAfter({}, __css, baseStyle, styleProps, sx)` — `sx` last, unconditionally winning.
 * `__css` sits BELOW a plain component's own baseStyle in that merge, so it would be silently
 * outranked by Stack's own `gap` / Flex's own `alignItems` whenever this component sets one —
 * confirmed by reading both chunks directly, not assumed. `item-variant.css.ts`'s own docblock
 * carries the matching note for its sibling files (image/colourSize/price).
 */
export const ZimmCartItem = {
  parts: ['row', 'details', 'info'],
  baseStyle: {
    row: {
      flexDirection: 'row',
      alignItems: 'flex-start',
      gap: 'var(--zimm-scale-xl)', // 24px mobile
      [`@media (min-width: ${breakpoints.md})`]: {
        alignItems: 'center',
        gap: 'var(--zimm-scale-700)', // 28px desktop
      },
    },
    details: {
      gap: 'var(--zimm-scale-xl)', // 24px mobile
      [`@media (min-width: ${breakpoints.md})`]: {
        gap: 'var(--zimm-scale-s)', // 12px desktop
      },
    },
    info: {
      flexDirection: 'row',
      justifyContent: 'space-between',
      alignItems: 'flex-end',
      [`@media (min-width: ${breakpoints.md})`]: {
        flexDirection: 'column',
        alignItems: 'flex-start',
        justifyContent: 'flex-start',
      },
    },
  },
};

import { breakpoints } from 'app/theme/foundation';

// Figma "Image" spec (product-item card, SFCC-270): 132x198 desktop, 67x100 mobile — no
// --zimm-scale equivalent exists at either pixel pair.
// audit-allow: Figma-confirmed cart-item image dimensions, no foundation token at this value.
const IMAGE_WIDTH_MOBILE = '67px';
const IMAGE_WIDTH_DESKTOP = '132px';

// Figma "colour + size" caption string: 200px, no --zimm-scale equivalent at this value.
// audit-allow: Figma-confirmed width, no foundation token at this value.
const COLOUR_SIZE_WIDTH = '200px';

/**
 * Co-located recipe for the item-variant family (item-image / item-attributes / item-price).
 * SFCC-270 (plan step 2.2).
 *
 * Parts:
 *   - `image` — item-image.tsx's outer Box: responsive width, ivory-200 background. Applied
 *     via `__css`, not `sx` — this one MUST stay overridable: order-summary/index.jsx (base
 *     SFCC, not yet overridden in this repo) calls
 *     `<CartItemVariantImage width="80px" mr={2} />` and depends on its own caller-supplied
 *     `width` winning over whatever default this component ships. `__css` is the lowest-
 *     priority slot in `@chakra-ui/system`'s `toCSSObject` merge (`chunk-E32MZNBA.mjs`:
 *     `assignAfter({}, __css, baseStyle, styleProps, sx)`), and `Box` carries no competing
 *     baseStyle of its own (`@chakra-ui/layout`'s `chunk-6CSUKJP7.mjs`: `var Box =
 *     chakra("div")`, no options) — confirmed by reading both files, not assumed — so a
 *     literal caller prop always wins over this part's `__css` default.
 *   - `img` — the inner <Image>: responsive objectFit (contain mobile / cover desktop) plus
 *     mix-blend-multiply, so the photo blends against the `image` part's ivory backdrop.
 *     `__css` is safe here too — Chakra's own `Image` (`@chakra-ui/image`'s
 *     `chunk-SMHKDLMK.mjs`) never sets a literal `__css` key of its own, unlike `Text` below.
 *   - `colourSize` — item-attributes.tsx's combined "colour, size" string.
 *   - `price` — item-price.tsx's price Stack (`textStyle: 'price'` only; the actual price
 *     digits render via the base, un-overridden `display-price`/`current-price` components,
 *     which set no competing font-size of their own — confirmed by reading both files — so
 *     the textStyle cascades down via ordinary CSS inheritance without touching either file).
 *
 * `colourSize` and `price` are applied via `sx`, not `__css`: Chakra's own `Text`
 * (`@chakra-ui/layout`'s `chunk-P74GIWPW.mjs`) places its OWN `__css={styles}` (from
 * `useStyleConfig('Text', props)`) as a literal key AFTER `...rest` in its own render call —
 * a caller-supplied `__css` prop would be silently discarded entirely there (a later
 * same-named key in one object literal replaces the earlier one; it does not merge). `sx` is
 * destructured separately by `toCSSObject` and isn't subject to that collision, so it's the
 * reliable way to style a plain `<Text>`/`<Stack>` from outside. Verified by reading the
 * compiled source directly. `price`'s own Stack has no such hazard (`@chakra-ui/layout`'s
 * `chunk-WKZT7ZXJ.mjs` Stack sets no literal `__css` key at all), so either mechanism would
 * have worked there — `sx` is used anyway, for one consistent rule across this file's parts
 * rather than a different mechanism per element.
 */
export const ZimmCartItemVariant = {
  parts: ['image', 'img', 'colourSize', 'price'],
  baseStyle: {
    image: {
      width: IMAGE_WIDTH_MOBILE,
      backgroundColor: 'var(--zimm-color-bg-02)',
      [`@media (min-width: ${breakpoints.md})`]: {
        width: IMAGE_WIDTH_DESKTOP,
      },
    },
    img: {
      objectFit: 'contain',
      mixBlendMode: 'multiply',
      [`@media (min-width: ${breakpoints.md})`]: {
        objectFit: 'cover',
      },
    },
    colourSize: {
      textStyle: 'caption',
      // Figma's colour+size string is the regular-weight "Default/Caption" node; this repo's
      // `caption` textStyle (theme/foundation/typography.ts) is medium-weight, matching the
      // different "Default/Caption-strong" node instead (confirmed: typography.ts's `caption`
      // entry sets `fontWeight: fontWeights.medium`). Overridden here rather than in
      // typography.ts (Tier 1, out of scope for a cart ticket) — same "cite the conflict at
      // the point of divergence" pattern zimmButton.css.ts's `sizes.lg`/`sizes.sm` fontSize
      // comment already uses for a leaked-default conflict of its own.
      fontWeight: 'var(--zimm-font-weight-regular)',
      width: COLOUR_SIZE_WIDTH,
      color: 'var(--zimm-color-text-secondary)',
    },
    price: {
      textStyle: 'price',
    },
  },
};

/*
 * Copyright (c) 2021, salesforce.com, inc.
 * All rights reserved.
 * SPDX-License-Identifier: BSD-3-Clause
 * For full license text, see the LICENSE file in the repo root or https://opensource.org/licenses/BSD-3-Clause
 */

/*
 * Copy-first port of node_modules/@salesforce/retail-react-app/app/components/item-variant/item-image.jsx
 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule (SFCC-270,
 * plan step 2.1). Zero functional diff at that step beyond the TypeScript annotations and a
 * temporary `[overrides]` console.log marker (verified live, then removed).
 *
 * `useItemVariant` is already imported via the relative `'.'` in the base file — unchanged here.
 *
 * SFCC-270 (plan step 2.2): restyled to the Figma cart-item spec. The outer Box's own literal
 * `width="84px" backgroundColor="gray.100"` defaults are gone, replaced by item-variant.css.ts's
 * `image` part via `__css` — kept as `__css`, not `sx`, specifically so a caller-supplied
 * `width`/`mr` (e.g. order-summary/index.jsx's base, not-yet-overridden
 * `<CartItemVariantImage width="80px" mr={2} />`) still wins; see that recipe's own docblock for
 * why. `{...props}` stays spread last, same defaults-then-spread order as before, still what
 * lets that caller-supplied width win. `ratio`'s default changed from `1` to the Figma-confirmed
 * 288/432 cart-item image ratio; the inner <Image> now also carries the `img` part's responsive
 * objectFit + mix-blend-multiply. Badge styling (Sale/Unavailable) is untouched — no Figma value
 * was given for it at this step.
 */
import React from 'react';
import {
  AspectRatio,
  Box,
  Badge,
  Image,
  useMultiStyleConfig,
} from '@salesforce/retail-react-app/app/components/shared/ui';
import { useItemVariant } from '.';
import { FormattedMessage } from 'react-intl';
import { findImageGroupBy } from '@salesforce/retail-react-app/app/utils/image-groups-utils';

// See index.tsx's own note on why this is `any` rather than a structural type.
type SfccVariant = any;

type ItemImageProps = {
  imageProps?: Record<string, any>;
  ratio?: number;
} & Record<string, any>;

const ZIMM_CART_ITEM_VARIANT_RECIPE = 'ZimmCartItemVariant';

// Figma "Image" spec, product-item card (SFCC-270): aspect ratio 288/432, which reduces to 2/3
// exactly. Matches the design record's own 132x198 desktop pair exactly (132 * 432/288 = 198);
// against the 67x100 mobile pair it lands at 100.5 — half a pixel over the stated 100, the same
// class of Figma-rounding gap zimmDrawer.css.ts's WIDTH_XLARGE note already documents for a
// different value, not something introduced here.
const CART_ITEM_IMAGE_RATIO = 288 / 432;

/**
 * In the context of a cart product item variant, this component renders the item's
 * main image.
 *
 * @todo = This component will render a `SALE` badge when the qualifier is available
 * on the custom property `c_isSale`. This will need to be expanded upon to handle
 * different badge/qualifiers and property names.
 */
const ItemImage = ({ imageProps, ratio = CART_ITEM_IMAGE_RATIO, ...props }: ItemImageProps) => {
  const variant: SfccVariant = useItemVariant();
  const styles = useMultiStyleConfig(ZIMM_CART_ITEM_VARIANT_RECIPE, {});

  // We find the 'small' images in the variant's image groups based on variationValues and pick the first one
  const image = findImageGroupBy(variant?.imageGroups, {
    viewType: 'small',
    selectedVariationAttributes: variant?.variationValues,
  })?.images?.[0];

  return (
    <Box __css={styles.image} {...props}>
      <AspectRatio ratio={ratio}>
        <Box position="relative">
          {variant.c_isSale && (
            <Badge
              position="absolute"
              top={0}
              left={0}
              marginLeft={2}
              marginTop={2}
              fontSize="10px"
              variant="solid"
              colorScheme="blue"
            >
              <FormattedMessage
                defaultMessage="Sale"
                id="item_image.label.sale"
                description="A sale badge placed on top of a product image"
              />
            </Badge>
          )}
          {variant.isProductUnavailable && (
            <Badge
              position="absolute"
              top={0}
              left={0}
              marginLeft={2}
              marginTop={2}
              fontSize="10px"
              variant="solid"
              colorScheme="red"
            >
              <FormattedMessage
                defaultMessage="Unavailable"
                id="item_image.label.unavailable"
                description="A unavailable badge placed on top of a product image"
              />
            </Badge>
          )}

          {image && (
            <Image
              alt={image.alt}
              src={`${image.disBaseLink || image.link}`}
              ignoreFallback={true}
              __css={styles.img}
              {...imageProps}
            />
          )}
        </Box>
      </AspectRatio>
    </Box>
  );
};

export default ItemImage;

