249	              {promos?.map((promo: SfccVariant) => (
250	                <Text key={promo?.id} fontSize="sm">
251	                  {promo?.calloutMsg}
252	                </Text>
253	              ))}
254	            </Stack>
255	          </PromoPopover>
256	        </Flex>
257	      )}
258	    </Stack>
259	  );
260	};
261	
